import 'package:flutter/material.dart';
import 'package:sehatak/core/models/eye/eye_models.dart';
import 'package:sehatak/core/services/eye_service.dart';
const _c=Color(0xFF9C27B0); const _icon='assets/icons/services/ophthalmology.png';
class EyeClinicDetailScreen extends StatelessWidget{final String clinicId;const EyeClinicDetailScreen({super.key,required this.clinicId});@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('تفاصيل عيادة العيون')),body:FutureBuilder<EyeClinic?>(future:EyeService().getClinic(clinicId),builder:(context,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());final d=s.data;if(d==null)return const Center(child:Text('العيادة غير متوفرة'));return ListView(padding:const EdgeInsets.all(16),children:[Container(height:160,alignment:Alignment.center,decoration:BoxDecoration(color:_c.withOpacity(.08),borderRadius:BorderRadius.circular(18)),child:Image.asset(_icon,width:90,height:90,errorBuilder:(_,__,___)=>const Icon(Icons.visibility,size:80,color:_c))),const SizedBox(height:14),Text(d.name,style:const TextStyle(fontSize:21,fontWeight:FontWeight.w800)),const SizedBox(height:8),Text(d.address),if(d.phone!=null)ListTile(leading:const Icon(Icons.phone),title:Text(d.phone!)),ListTile(leading:const Icon(Icons.star,color:Colors.amber),title:Text('${d.rating.toStringAsFixed(1)} (${d.reviewCount} تقييم)')),if(d.services.isNotEmpty)Wrap(spacing:8,runSpacing:8,children:d.services.map((e)=>Chip(label:Text(e),backgroundColor:_c.withOpacity(.08))).toList())]);});}
